-- ============ SEED RECIPES — MealsUp (v2, données réelles) ============
-- À exécuter dans le SQL Editor de Supabase, APRÈS schema.sql.
--
-- PROVENANCE DES DONNÉES (temps, quantités, instructions) :
--   - 28 recettes (8 françaises + 20 internationales) proviennent du jeu de
--     données ouvert "UniTools Recipes" (https://theunitools.com/recipes),
--     501 recettes de 127 pays, licence CC BY-SA 4.0 — attribution requise :
--     "Recette adaptée de UniTools — theunitools.com (CC BY-SA 4.0)".
--     Traduites de l'anglais vers le français pour cette app.
--   - 17 recettes françaises supplémentaires sont rédigées à la main (aucune
--     base de données ouverte et gratuite ne couvre la cuisine française en
--     profondeur — TheMealDB et UniTools n'en ont respectivement que 0 et 8).
--     Temps et quantités reflètent une pratique culinaire réaliste, mais ne
--     sont pas tirés d'une source externe vérifiable — à affiner si besoin.
--
-- Idempotent : peut être rejoué. Les recettes existantes (même titre) sont
-- mises à jour avec les nouvelles données plutôt qu'ignorées, pour remplacer
-- proprement d'anciennes données moins précises.

INSERT INTO recipes (title, description, prep_time_mins, cook_time_mins, servings, difficulty, dietary_type, tags, visibility, equipment_needed, instructions) VALUES

-- ===== Françaises (réelles — UniTools CC BY-SA 4.0) =====
('Ratatouille', 'Un ragoût de légumes provençal où chaque légume cuit séparément avant de se retrouver — sinon, tout se transforme en bouillie.', 20, 45, 4, 1, 'light', '["français","végétarien","provençal"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire revenir l''aubergine à feu vif dans deux cuillères d''huile jusqu''à ce que les bords dorent, puis réserver — l''aubergine boit l''huile aussitôt, ne pas en rajouter, elle la restituera plus tard.","Dans la même poêle, faire dorer la courgette 4 min et l''ajouter à l''aubergine ; elle doit rester ferme.","Faire revenir le poivron jusqu''à tendreté avec quelques marques de brûlé, puis réserver aussi.","Dans l''huile restante, suer l''oignon, ajouter l''ail et le thym 30 secondes jusqu''à ce que ça embaume.","Ajouter les tomates et laisser réduire en sauce épaisse à feu moyen, environ 20 min.","Remettre les légumes dans la poêle, assaisonner et réchauffer ensemble 10 min à feu doux. Retirer du feu, ajouter le basilic et laisser reposer : la ratatouille est meilleure tiède que chaude."]'::jsonb),
('Soupe à l''oignon gratinée', 'Une soupe d''oignons, de bouillon et de pain gratiné. Toute la saveur vient de la caramélisation, qui prend quarante minutes et non vingt.', 15, 60, 4, 1, 'light', '["français","soupe","réconfortant"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre le beurre dans une cocotte, ajouter les oignons et une pincée de sel, laisser à feu moyen en remuant régulièrement — les vingt premières minutes, les oignons rendent leur eau.","La caramélisation commence ensuite : encore vingt-cinq minutes pour les amener à la couleur du thé fort. S''ils accrochent, baisser le feu et ajouter une cuillère d''eau.","Ajouter la farine et cuire deux minutes pour perdre le goût cru.","Verser le vin en grattant le fond, laisser réduire de moitié.","Ajouter le bouillon et le thym, porter à ébullition et mijoter 20 min. Rectifier l''assaisonnement en fin de cuisson.","Répartir dans des bols allant au four, garnir chacun d''une tranche de baguette, couvrir de fromage et passer sous le grill jusqu''à ce que ça bouillonne et dore, environ 3 min."]'::jsonb),
('Coq au vin', 'Poulet braisé au vin rouge avec lardons, champignons et petits oignons. Mariner la veille fait la moitié du travail.', 30, 90, 4, 2, 'gras', '["français","mijoté","classique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir le poulet de vin avec carotte, ail et herbes, laisser mariner au frais toute la nuit. Le matin, égoutter la viande et la sécher en gardant le vin.","Faire revenir les lardons dans une cocotte et les réserver. Dans cette graisse, faire dorer le poulet sur toutes les faces, en plusieurs fois.","Saupoudrer de farine, mélanger et cuire 2 min. Verser la marinade avec ses légumes et le bouillon, porter à ébullition et écumer.","Braiser à couvert à feu très doux ou 1h au four à 160°C. La sauce doit à peine frémir.","Pendant ce temps, faire dorer les oignons au beurre et, séparément, les champignons à feu vif jusqu''à coloration.","Ajouter oignons, champignons et lardons à la cocotte, laisser 10 min à feu doux et rectifier l''assaisonnement."]'::jsonb),
('Crème brûlée', 'Une crème aux jaunes d''œufs cuite au bain-marie sous une croûte de sucre brûlé.', 20, 45, 4, 2, 'gras', '["français","dessert","four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Fendre la vanille, gratter les graines dans la crème et chauffer jusqu''à frémissement. Retirer du feu et laisser infuser 15 min.","Travailler les jaunes et le sucre sans incorporer d''air — pas de mousse ici. Verser la crème tiède en filet en remuant.","Filtrer au tamis, écumer la mousse en surface, répartir dans des ramequins posés dans un plat profond.","Verser de l''eau bouillante dans le plat jusqu''à mi-hauteur des ramequins et cuire 40 min à 150°C. Le centre doit encore trembler.","Laisser refroidir complètement puis réfrigérer au moins 4h. Saupoudrer de sucre et caraméliser au chalumeau juste avant de servir."]'::jsonb),
('Quiche lorraine', 'Une pâte brisée garnie de lardons et d''un appareil œufs-crème. Ni fromage ni oignon — la recette classique n''en contient pas.', 40, 60, 6, 2, 'gras', '["français","four","classique"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sabler le beurre froid et la farine avec une pincée de sel, ajouter l''œuf et l''eau glacée et rassembler la pâte sans pétrir. Réfrigérer 1h.","Étaler la pâte, foncer le moule, piquer et réfrigérer encore 20 min : c''est ce qui l''empêche de se rétracter.","Couvrir de papier et de billes de cuisson, cuire à blanc 15 min à 190°C, retirer les billes et poursuivre 5 min pour une base sèche.","Faire dorer les lardons et les égoutter sur papier absorbant — trop de gras ferait trancher l''appareil.","Battre les œufs avec la crème et le lait sans mousser, assaisonner de muscade et de poivre. Peu de sel : les lardons en apportent déjà.","Répartir les lardons sur le fond, verser l''appareil et cuire 35 min à 170°C. Le centre doit encore trembler légèrement à la sortie du four."]'::jsonb),
('Croissant', 'Une pâte levée feuilletée à vingt-sept couches de beurre. Tout se joue sur la température : pâte et beurre doivent être également froids.', 180, 20, 8, 3, 'gras', '["français","boulangerie","four","petit-déjeuner","goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Mélanger farine, lait froid, levure, sucre, sel et beurre mou pendant 5 min, pas plus, pour ne pas trop développer le gluten.","Aplatir la pâte en rectangle, filmer et réfrigérer au moins 4h, idéalement toute la nuit.","Taper le beurre froid au rouleau en carré d''un centimètre d''épaisseur et le garder froid : il doit plier sans casser ni fondre.","Étaler la pâte deux fois plus grande que le carré de beurre, le placer au centre et rabattre les bords comme une enveloppe en soudant les joints.","Étaler en long rectangle et plier en trois. Réfrigérer 40 min. Répéter deux fois — trois tours en tout.","Abaisser la pâte à 4mm, découper des triangles de dix centimètres de base et les rouler de la base vers la pointe en étirant légèrement.","Pousser 2h à 25°C, pas plus chaud sous peine de faire fondre le beurre. Dorer à l''œuf et cuire 18 min à 200°C."]'::jsonb),
('Bouillabaisse', 'La soupe de poissons marseillaise, plusieurs espèces, safran et sauce rouille.', 50, 70, 6, 3, 'protéiné', '["français","poisson","provençal"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire suer oignon, poireau et fenouil dans l''huile d''olive 10 min.","Ajouter les petits poissons entiers, les tomates, l''ail, le zeste et le safran, cuire 5 min.","Mouiller avec 2 litres d''eau, porter à ébullition et cuire 40 min à découvert.","Passer le tout au moulin à légumes en pressant bien la chair, puis remettre le bouillon dans la marmite.","Cuire les pommes de terre dans le bouillon 15 min, puis ajouter les gros poissons dans l''ordre, les plus fermes d''abord.","Préparer la rouille : jaune d''œuf, ail, safran, une pincée de piment de Cayenne et huile d''olive versée en filet.","Servir le bouillon en bol avec croûtons et rouille, et les poissons avec les pommes de terre sur un plat à part."]'::jsonb),
('Tarte Tatin', 'Une tarte aux pommes renversée : les pommes caramélisent au fond, la pâte se pose dessus et devient la base.', 30, 60, 8, 2, 'gras', '["français","dessert","four"]'::jsonb, 'public', '["stovetop","oven"]'::jsonb, '["Éplucher les pommes, les couper en deux, les épépiner et les arroser de citron.","Faire fondre le sucre dans une poêle en fonte à feu moyen jusqu''à caramel ambré, sans remuer à la cuillère.","Retirer du feu et incorporer le beurre morceau par morceau, avec la vanille et une pincée de sel.","Ranger les demi-pommes côté coupé vers le haut, serrées les unes contre les autres, en cercle.","Cuire sur le feu 20 min à feu moyen, jusqu''à ce que les pommes s''affaissent et s''imprègnent de caramel.","Couvrir d''un disque de pâte feuilletée en rentrant les bords à l''intérieur de la poêle, piquer à plusieurs endroits.","Cuire 40 min à 200°C, laisser reposer 5 min et renverser sur un plat d''un geste franc."]'::jsonb),

-- ===== Françaises (rédigées à la main — pas de base ouverte disponible) =====
('Blanquette de veau', 'Veau mijoté dans un bouillon clair, lié à la crème et au jaune d''œuf, avec carottes et champignons.', 25, 90, 4, 2, 'protéiné', '["français","mijoté","classique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir le veau d''eau froide, porter à ébullition et écumer soigneusement pendant 5 min.","Ajouter carottes, oignon clouté, poireau et bouquet garni, saler légèrement et mijoter à couvert 1h15 à feu doux.","Retirer la viande et les légumes du bouillon, filtrer le bouillon et le réserver.","Préparer un roux blanc avec le beurre et la farine, mouiller peu à peu avec le bouillon chaud en fouettant jusqu''à consistance nappante.","Ajouter les champignons émincés et laisser cuire 10 min dans la sauce.","Remettre la viande et les légumes dans la sauce, réchauffer sans bouillir. Lier hors du feu avec les jaunes d''œufs, la crème et un filet de citron."]'::jsonb),
('Cassoulet', 'Haricots blancs mijotés avec saucisse, porc et confit de canard, gratinés au four.', 30, 150, 6, 2, 'gras', '["français","mijoté","famille","hiver"]'::jsonb, 'public', '["stovetop","oven"]'::jsonb, '["Cuire les haricots égouttés à l''eau froide non salée avec la couenne, un oignon et le bouquet garni pendant 1h, jusqu''à tendreté.","Pendant ce temps, faire dorer la poitrine de porc coupée en morceaux et les saucisses entières dans une cocotte.","Faire revenir l''oignon restant et les carottes, ajouter l''ail et le concentré de tomate, cuire 2 min.","Égoutter les haricots en gardant le bouillon, les ajouter à la cocotte avec le porc, les saucisses, le confit et assez de bouillon pour couvrir.","Mijoter à couvert 45 min à feu doux, puis transférer dans un plat à gratin, parsemer de chapelure.","Cuire au four à 160°C pendant 45 min en cassant la croûte formée deux ou trois fois et en la reformant à chaque fois."]'::jsonb),
('Pot-au-feu', 'Bœuf et légumes-racines mijotés longuement dans un bouillon clair, servi en deux temps : bouillon puis viande.', 30, 180, 6, 1, 'protéiné', '["français","mijoté","famille","économique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir les viandes d''eau froide, porter lentement à ébullition et écumer soigneusement pendant 10 min.","Ajouter les oignons cloutés, l''ail et le bouquet garni, saler et laisser mijoter à découvert et à petits frémissements pendant 2h.","Ajouter les carottes et les navets, poursuivre la cuisson 40 min.","Ajouter poireaux et céleri, cuire encore 30 min jusqu''à ce que viande et légumes soient bien tendres.","Envelopper les os à moelle dans une mousseline et les pocher 20 min dans le bouillon.","Servir le bouillon en entrée avec du pain grillé et la moelle, puis la viande et les légumes avec gros sel et moutarde."]'::jsonb),
('Gratin dauphinois', 'Pommes de terre en fines lamelles cuites lentement dans la crème et le lait, sans œuf ni fromage dans la version traditionnelle.', 20, 75, 6, 1, 'gras', '["français","accompagnement","économique","four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Éplucher et couper les pommes de terre en fines rondelles régulières, sans les rincer pour garder leur amidon.","Frotter un plat à gratin avec l''ail puis le beurrer généreusement.","Disposer les pommes de terre en couches régulières, saler, poivrer et râper un peu de muscade entre chaque couche.","Chauffer la crème et le lait sans bouillir, verser sur les pommes de terre jusqu''à affleurement.","Cuire à 150°C pendant 1h15, jusqu''à ce qu''un couteau s''enfonce sans résistance et que le dessus soit doré.","Laisser reposer 10 min avant de servir : le gratin se tient mieux tiède que brûlant."]'::jsonb),
('Salade niçoise', 'Une salade méditerranéenne fraîche à base de légumes crus, thon ou anchois, œufs durs et olives.', 20, 10, 4, 1, 'light', '["français","salade","méditerranéen","léger"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les œufs 9 min dans l''eau bouillante, les refroidir à l''eau froide et les écaler.","Couper les tomates en quartiers, le poivron et le concombre en tranches, émincer finement l''oignon rouge.","Disposer les légumes sur un plat, ajouter le thon émietté ou les filets d''anchois et les olives.","Couper les œufs en quartiers et les répartir sur la salade.","Mélanger huile d''olive, vinaigre, sel et poivre, arroser la salade et parsemer de basilic ciselé juste avant de servir."]'::jsonb),
('Croque-monsieur', 'Un sandwich chaud au jambon et à la béchamel, gratiné au fromage.', 10, 10, 2, 1, 'gras', '["français","rapide","économique","étudiant"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Préparer une béchamel : fondre le beurre, ajouter la farine, cuire 1 min, verser le lait chaud en fouettant jusqu''à épaississement. Assaisonner de muscade et de moutarde.","Tartiner deux tranches de pain de béchamel, garnir de jambon et d''un peu de fromage, refermer avec les tranches restantes.","Napper le dessus de béchamel et parsemer généreusement de fromage râpé.","Cuire à la poêle à feu doux à couvert, ou 8 min au four à 200°C, jusqu''à ce que le fromage soit doré et fondant."]'::jsonb),
('Mousse au chocolat', 'Chocolat noir fondu et blancs en neige, sans crème ni gélatine — la texture vient uniquement de l''air battu.', 20, 5, 6, 1, 'gras', '["français","dessert","économique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre le chocolat au bain-marie ou à faible puissance au micro-ondes, en remuant, puis laisser tiédir.","Séparer les blancs des jaunes. Incorporer les jaunes un à un dans le chocolat tiède.","Monter les blancs en neige ferme avec une pincée de sel, en ajoutant le sucre en pluie à mi-parcours.","Incorporer un tiers des blancs au chocolat pour le détendre, puis le reste délicatement à la maryse, en soulevant la masse.","Répartir dans des verrines et réfrigérer au moins 4h avant de servir."]'::jsonb),
('Crêpes', 'Une pâte fine à base de farine, œufs et lait, cuite à la poêle bien chaude.', 15, 20, 4, 1, 'gras', '["français","économique","étudiant","petit-déjeuner","goûter"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger la farine, le sucre et le sel dans un saladier, creuser un puits et casser les œufs au centre.","Fouetter en incorporant peu à peu le lait pour éviter les grumeaux, jusqu''à obtenir une pâte lisse et fluide.","Ajouter le beurre fondu et l''arôme choisi, laisser reposer la pâte 30 min à température ambiante.","Chauffer une poêle légèrement huilée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour l''étaler finement.","Cuire 1 à 2 min jusqu''à ce que les bords se détachent, retourner et cuire 1 min de plus. Empiler les crêpes au fur et à mesure."]'::jsonb),
('Tarte aux pommes', 'Une pâte brisée garnie de pommes fines, simple et rapide, sans crème pâtissière.', 25, 40, 8, 1, 'gras', '["français","dessert","économique","four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Foncer un moule à tarte avec la pâte brisée, piquer le fond à la fourchette.","Éplucher et couper les pommes en fines tranches régulières.","Disposer les tranches en rosace sur la pâte, en cercles concentriques serrés.","Saupoudrer de sucre et de cannelle, parsemer de petits morceaux de beurre.","Cuire 40 min à 190°C jusqu''à ce que les pommes soient dorées et la pâte cuite.","Chauffer légèrement la confiture d''abricot et en badigeonner la tarte tiède pour la faire briller."]'::jsonb),
('Poulet basquaise', 'Poulet mijoté avec poivrons, tomates et piment d''Espelette, spécialité du Pays basque.', 20, 50, 4, 1, 'protéiné', '["français","mijoté","famille"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer les morceaux de poulet dans l''huile d''olive sur toutes les faces, puis réserver.","Dans la même cocotte, faire revenir oignon, poivrons et jambon 8 min jusqu''à ce qu''ils ramollissent.","Ajouter l''ail, les tomates concassées et le piment d''Espelette, cuire 5 min.","Remettre le poulet dans la cocotte, déglacer au vin blanc, couvrir et mijoter 35 min à feu doux.","Rectifier l''assaisonnement et servir avec du riz blanc."]'::jsonb),
('Choucroute garnie', 'Chou fermenté mijoté au vin blanc avec charcuteries variées, spécialité alsacienne.', 20, 90, 6, 2, 'gras', '["français","famille","hiver"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer la choucroute et l''essorer légèrement. Faire fondre la graisse d''oie dans une grande cocotte et y faire revenir l''oignon émincé.","Ajouter la choucroute, le lard, les baies de genièvre et le vin blanc, mélanger.","Enfouir la poitrine fumée et le jarret dans la choucroute, couvrir et mijoter 1h15 à feu doux.","Ajouter les pommes de terre épluchées entières et poursuivre la cuisson 25 min.","Ajouter les saucisses pour les 10 dernières minutes, juste pour les réchauffer.","Dresser la choucroute avec les viandes tranchées, les saucisses et les pommes de terre autour."]'::jsonb),
('Clafoutis aux cerises', 'Un appareil à flan versé sur des cerises entières et cuit au four, dessert économique et rapide.', 15, 40, 6, 1, 'gras', '["français","dessert","économique","four","goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Beurrer un plat à gratin et y répartir les cerises en une couche régulière.","Fouetter les œufs avec le sucre jusqu''à blanchiment, ajouter la farine et le sel en mélangeant.","Incorporer le lait petit à petit pour obtenir une pâte lisse et fluide, ajouter la vanille.","Verser l''appareil sur les cerises.","Cuire 40 min à 180°C jusqu''à ce que le clafoutis soit doré et pris au centre.","Servir tiède, saupoudré de sucre glace si désiré."]'::jsonb),
('Tartiflette', 'Pommes de terre, lardons et oignons gratinés sous un reblochon fondant, spécialité savoyarde.', 20, 45, 4, 1, 'gras', '["français","famille","four","montagne"]'::jsonb, 'public', '["stovetop","oven"]'::jsonb, '["Cuire les pommes de terre en robe des champs 20 min à l''eau bouillante, puis les éplucher et les couper en rondelles épaisses.","Faire revenir les lardons et l''oignon émincé dans une poêle jusqu''à coloration.","Déglacer au vin blanc, laisser réduire, puis ajouter la crème fraîche et mélanger.","Disposer la moitié des pommes de terre dans un plat à gratin, couvrir de la moitié du mélange lardons-oignons, répéter.","Couper le reblochon en deux dans l''épaisseur et le poser croûte vers le haut sur le gratin.","Cuire 25 min à 200°C jusqu''à ce que le fromage soit doré et bouillonnant."]'::jsonb),
('Œufs mimosa', 'Des œufs durs coupés en deux, jaunes mélangés à la mayonnaise et remis en dôme, classique d''entrée économique.', 20, 10, 4, 1, 'protéiné', '["français","entrée","économique","apéro"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les œufs 10 min à l''eau bouillante, les refroidir à l''eau froide et les écaler.","Couper les œufs en deux dans la longueur, retirer délicatement les jaunes et les réserver dans un bol.","Écraser les jaunes à la fourchette avec la mayonnaise et la moutarde jusqu''à obtenir une pâte lisse, assaisonner.","Garnir les blancs d''œufs de ce mélange à la cuillère ou à la poche, en formant un petit dôme.","Parsemer de ciboulette ciselée et d''une pincée de paprika avant de servir frais."]'::jsonb),
('Far breton', 'Un flan dense aux pruneaux, spécialité bretonne simple et bon marché.', 15, 45, 8, 1, 'gras', '["français","dessert","économique","four","goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Faire tremper les pruneaux dans le rhum tiède pendant 30 min.","Fouetter les œufs avec le sucre jusqu''à blanchiment, ajouter la farine et le sel en mélangeant bien.","Incorporer le lait petit à petit puis le beurre fondu, jusqu''à obtenir une pâte lisse.","Beurrer un plat, y répartir les pruneaux égouttés et verser la pâte dessus.","Cuire 45 min à 180°C jusqu''à ce que le far soit doré et pris, encore légèrement tremblant au centre.","Laisser refroidir avant de découper en parts."]'::jsonb),
('Soupe au pistou', 'Une soupe de légumes d''été liée au pistou de basilic, ail et parmesan, sans viande.', 25, 45, 6, 1, 'light', '["français","soupe","végétarien","été"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper tous les légumes en petits dés et les mettre dans une grande marmite avec 2 litres d''eau salée.","Porter à ébullition et cuire 30 min jusqu''à ce que les légumes soient tendres.","Ajouter les vermicelles et cuire encore 8 min.","Pendant ce temps, piler le basilic, l''ail et le parmesan au mortier, puis incorporer l''huile d''olive en filet pour obtenir une pâte homogène : le pistou.","Servir la soupe bien chaude avec une cuillère de pistou ajoutée au moment de manger, pour préserver sa fraîcheur."]'::jsonb),
('Camembert rôti au four', 'Un camembert entier fondu au four, à tartiner à la cuillère — apéritif rapide et convivial.', 5, 20, 4, 1, 'gras', '["français","apéro","rapide","économique"]'::jsonb, 'public', '["oven"]'::jsonb, '["Retirer l''emballage plastique du camembert et le remettre dans sa boîte en bois, sur le papier.","Inciser le dessus en croisillons, insérer de fines lamelles d''ail dans les entailles.","Parsemer de thym, arroser de miel et parsemer de noix concassées.","Cuire 20 min à 180°C jusqu''à ce que le centre soit coulant.","Servir aussitôt avec des tranches de baguette à tremper dedans."]'::jsonb),

-- ===== Internationales (réelles — UniTools CC BY-SA 4.0) =====
('Spaghetti carbonara', 'Pâtes à base de quatre ingrédients : guanciale, œufs, pecorino et poivre. Sans crème, il n''y en a jamais eu.', 10, 15, 2, 2, 'gras', '["italien","pâtes","rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter une grande casserole d''eau à ébullition et bien la saler — c''est le seul sel du plat.","Mettre le guanciale dans une poêle froide et chauffer à feu moyen jusqu''à ce qu''il soit doré et croustillant, 6-8 min.","Pendant ce temps, battre les jaunes, l''œuf entier, le pecorino râpé et le poivre en pâte épaisse, à température ambiante.","Cuire les spaghetti une minute de moins que le temps indiqué, en réservant un verre d''eau de cuisson avant l''égouttage.","Hors du feu, ajouter les pâtes à la poêle et mélanger avec la graisse. Laisser tiédir 20 secondes.","Verser le mélange aux œufs et mélanger vivement en ajoutant l''eau de cuisson jusqu''à obtenir une sauce lisse et nappante. Servir aussitôt."]'::jsonb),
('Risotto alla milanese', 'Risotto au safran, à base de bouillon et d''un brassage quasi constant qui libère l''amidon du riz.', 10, 25, 4, 2, 'gras', '["italien","végétarien","riz"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Infuser le safran dans une louche de bouillon chaud ; garder le reste du bouillon frémissant.","Faire fondre la moitié du beurre et suer l''oignon à feu doux jusqu''à ce qu''il soit translucide, environ 8 min.","Ajouter le riz et remuer 2 min jusqu''à ce que les grains soient nacrés (la tostatura).","Verser le vin et laisser s''évaporer complètement.","Ajouter le bouillon louche par louche en remuant, environ 18 min, jusqu''à ce que le riz soit crémeux à l''extérieur et encore ferme au centre.","Incorporer le safran, retirer du feu et ajouter le beurre froid et le parmesan en secouant la casserole pour lier le risotto."]'::jsonb),
('Pizza margherita', 'Une pâte longuement fermentée, tomate crue, mozzarella et basilic. Ici, c''est le temps qui fait tout, pas le nombre d''ingrédients.', 60, 10, 4, 2, 'gras', '["italien","végétarien","four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Dissoudre la levure dans l''eau, ajouter la farine et mélanger grossièrement. Laisser reposer 20 min puis incorporer le sel et pétrir 10 min.","Laisser lever 2h à température ambiante, diviser en 4 pâtons et réfrigérer 24h.","Sortir la pâte 3h avant la cuisson. Écraser les tomates à la main avec une pincée de sel pour la sauce.","Préchauffer le four avec une pierre ou plaque à sa puissance maximale pendant au moins 1h.","Étaler un pâton du centre vers les bords avec les doigts, sans rouleau, en laissant la bordure intacte.","Étaler une fine couche de sauce, ajouter la mozzarella et un filet d''huile. Cuire 7-9 min jusqu''à ce que la bordure soit marbrée, puis ajouter le basilic."]'::jsonb),
('Lasagnes bolognaise', 'Pâtes, ragù et béchamel en couches. Le ragù mijote trois heures au lait et au vin plutôt qu''à la tomate.', 40, 220, 8, 3, 'gras', '["italien","four","famille"]'::jsonb, 'public', '["stovetop","oven"]'::jsonb, '["Faire revenir la pancetta, ajouter les légumes et laisser suer 20 min à feu doux jusqu''à ce qu''ils fondent complètement.","Ajouter les viandes et cuire à feu vif en écrasant les morceaux jusqu''à évaporation complète de l''eau et début de coloration.","Verser le lait et laisser réduire à sec (20 min), puis le vin de la même façon.","Ajouter le concentré de tomate et le bouillon, porter à ébullition et mijoter 3h à feu très doux.","Préparer la béchamel : fondre le beurre, ajouter la farine, cuire 1 min puis verser le lait chaud en filet en fouettant. Assaisonner à la muscade.","Monter les couches : béchamel, pâtes, ragù, béchamel, parmesan — six fois. Terminer par de la béchamel et du parmesan.","Cuire à 180°C pendant 40 min, les 10 dernières minutes à découvert. Laisser reposer 20 min avant de découper."]'::jsonb),
('Tiramisu', 'Biscuits savoiardi imbibés de café sous une crème au mascarpone. Sans cuisson, mais deux étapes où tout peut basculer.', 30, 0, 6, 2, 'gras', '["italien","dessert","sans cuisson"]'::jsonb, 'public', '[]'::jsonb, '["Fouetter les jaunes avec la moitié du sucre au bain-marie sans toucher l''eau, jusqu''à blanchir et épaissir, environ 7 min. Laisser refroidir.","Incorporer le mascarpone froid à la cuillère, jamais au fouet électrique, sinon la crème devient granuleuse.","Monter les blancs avec le reste du sucre en pics fermes et les incorporer délicatement en trois fois.","Mélanger le café et le marsala. Tremper chaque biscuit une seconde par face et les disposer en couche serrée.","Étaler la moitié de la crème, répéter une couche de biscuits et de crème. Couvrir et réfrigérer au moins 6h, idéalement toute la nuit.","Saupoudrer de cacao au tamis juste avant de servir."]'::jsonb),
('Soupe miso', 'Une soupe de dashi et miso prête en dix minutes. Le miso ne doit jamais bouillir, sous peine de perdre arôme et intérêt.', 5, 15, 4, 1, 'light', '["japonais","soupe","rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir le kombu d''eau froide et chauffer doucement jusqu''à frémissement, environ 10 min ; retirer l''algue avant l''ébullition.","Porter l''eau à ébullition, ajouter les copeaux de bonite, retirer du feu aussitôt et laisser infuser 2 min.","Filtrer sans presser les copeaux, sous peine d''amertume.","Faire tremper le wakame 5 min dans l''eau froide.","Réchauffer le dashi, ajouter le tofu et le wakame, chauffer doucement 2 min.","Délayer le miso dans une louche de bouillon chaud, remettre dans la casserole et retirer immédiatement du feu. Parsemer d''oignon nouveau."]'::jsonb),
('Ramen shoyu', 'Bouillon, tare et huile assemblés dans le bol plutôt que cuits ensemble.', 30, 180, 4, 3, 'protéiné', '["japonais","soupe","mijoté"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir les carcasses d''eau froide, porter à ébullition 10 min puis jeter l''eau et rincer les os et la marmite.","Recouvrir d''eau fraîche, ajouter gingembre et ail, mijoter 3h. Ajouter le kombu 20 min avant la fin et le retirer avant ébullition.","Pour le tare, réduire la sauce soja, le mirin, le saké et les shiitake d''un tiers.","Cuire les œufs 6 min 30, les refroidir dans l''eau glacée, les écaler et les laisser mariner 2h dans le tare restant.","Cuire les nouilles séparément selon le temps indiqué, les égoutter et les déposer sur le tare au fond des bols.","Verser le bouillon bouillant, ajouter le porc, l''œuf et l''oignon nouveau, terminer avec l''huile de sésame."]'::jsonb),
('Tempura', 'Légumes et crevettes dans une pâte glacée et grumeleuse. La lisser complètement serait justement l''erreur à ne pas commettre.', 25, 20, 4, 2, 'light', '["japonais","friture"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Inciser les crevettes trois fois sur la face intérieure pour les empêcher de s''enrouler à la cuisson.","Mélanger dashi, soja et mirin, porter à ébullition puis retirer du feu : c''est le tentsuyu, à servir avec le daikon râpé.","Chauffer l''huile à 180°C. Ne préparer la pâte qu''une fois l''huile prête.","Battre l''œuf froid dans l''eau glacée, ajouter farine et fécule et mélanger 5-6 coups aux baguettes, sans lisser.","Fariner les morceaux, les tremper dans la pâte et les plonger par 3-4 dans l''huile. Frire 1 à 2 min.","Égoutter sur une grille, jamais sur du papier, en écumant les résidus de pâte entre les fournées."]'::jsonb),
('Guacamole', 'Avocat, citron vert, oignon et piment écrasés à la fourchette. Ni mixeur ni crème fraîche : les deux en feraient une simple sauce.', 15, 0, 4, 1, 'light', '["mexicain","apéro","sans cuisson","végan"]'::jsonb, 'public', '[]'::jsonb, '["Couper les avocats en deux, retirer les noyaux et prélever la chair.","Ajouter aussitôt le jus de citron vert et le sel, avant que la chair ne s''oxyde.","Écraser à la fourchette en une purée grossière, en laissant des morceaux.","Incorporer l''oignon, le jalapeño et la coriandre, goûter et rectifier. Ajouter la tomate en dernier, délicatement.","Servir aussitôt ; si besoin d''attendre, filmer au contact pour éviter l''oxydation."]'::jsonb),
('Tacos al pastor', 'Porc mariné aux piments séchés et à l''ananas, saisi jusqu''à caraméliser, dans une tortilla de maïs.', 30, 20, 4, 2, 'protéiné', '["mexicain","épicé"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Épépiner les piments et les torréfier à sec 20 secondes par face, puis les couvrir d''eau bouillante 15 min.","Mixer les piments réhydratés avec la moitié de l''ananas, l''achiote, le vinaigre, l''ail, le cumin et l''origan en pâte lisse.","Enrober le porc de marinade et laisser reposer au moins 2h, idéalement toute la nuit (pas plus de 24h).","Saisir la viande par petites quantités dans une poêle très chaude, 2 min par face, sans remuer jusqu''à coloration.","Saisir le reste de l''ananas dans la même poêle et le couper en dés. Hacher la viande, réchauffer les tortillas 20 sec par face et garnir : viande, ananas, oignon, coriandre, citron vert."]'::jsonb),
('Paella valenciana', 'Riz en large poêle avec poulet, lapin et haricots. On ne le remue jamais une fois le riz versé — c''est ce qui donne la croûte du fond.', 25, 45, 4, 2, 'protéiné', '["espagnol","riz","famille"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Chauffer l''huile dans une large poêle et faire dorer le poulet et le lapin sur toutes les faces, environ un quart d''heure.","Pousser la viande sur les bords, faire revenir les haricots verts au centre, ajouter la tomate râpée et le paprika et cuire jusqu''à ce que la tomate perde son goût cru.","Verser le bouillon, ajouter romarin, safran et haricots blancs, saler franchement et laisser bouillir 10 min.","Répartir le riz en couche régulière et l''égaliser une fois à la cuillère. Ne plus toucher la poêle ensuite.","Cuire à feu vif 10 min puis à feu moyen 8 min de plus, jusqu''à absorption du bouillon.","Monter le feu 30 secondes pour obtenir le socarrat (le riz doit crépiter plutôt que bouillonner), puis couvrir d''un linge et laisser reposer 5 min."]'::jsonb),
('Moussaka', 'Aubergines, sauce à la viande et à la cannelle, épaisse couche de béchamel, cuites au four jusqu''à bien se tenir.', 40, 75, 6, 3, 'gras', '["grec","four","famille"]'::jsonb, 'public', '["oven"]'::jsonb, '["Saler les tranches d''aubergine et les laisser dégorger 30 min, les éponger, les badigeonner d''huile et les rôtir 20 min à 200°C.","Faire revenir l''oignon, ajouter la viande hachée et cuire en l''émiettant jusqu''à évaporation totale de l''eau. Déglacer au vin et laisser réduire.","Ajouter ail, tomates et cannelle, mijoter 20 min jusqu''à obtenir une sauce épaisse.","Préparer la béchamel : fondre le beurre, ajouter la farine, cuire 1 min, verser le lait chaud en fouettant. Hors du feu, ajouter muscade, jaunes d''œufs et la moitié du fromage.","Monter les couches : pomme de terre, aubergine, sauce à la viande, aubergine à nouveau. Napper de béchamel et parsemer du reste de fromage.","Cuire 45 min à 180°C jusqu''à coloration dorée. Laisser reposer 30 min avant de découper."]'::jsonb),
('Souvlaki', 'Porc en brochettes au citron, origan et huile d''olive, cuit rapidement à feu vif.', 20, 15, 4, 1, 'protéiné', '["grec","grillade","rapide"]'::jsonb, 'public', '["grill"]'::jsonb, '["Mélanger huile, jus et zeste de citron, origan, ail écrasé, sel et poivre. Enrober la viande et laisser mariner 2h maximum 4h.","Pendant ce temps, préparer le tzatziki : yaourt, concombre pressé, une gousse d''ail, une cuillère d''huile et du sel.","Enfiler la viande sur les brochettes sans trop serrer, pour que la chaleur circule entre les morceaux.","Cuire sur grill ou plancha chaude, 3 min sur chacune des 4 faces, jusqu''à belle coloration.","Laisser reposer 5 min, réchauffer les pitas 30 sec par face et servir avec le tzatziki et du citron."]'::jsonb),
('Fattet hommous', 'Des couches de pain pita frit, de pois chiches chauds et de yaourt à l''ail, avec du beurre doré et des pignons.', 20, 90, 5, 1, 'light', '["libanais","végétarien"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pois chiches à l''eau non salée 1h30 jusqu''à tendreté complète, en gardant l''eau de cuisson.","Déchirer les pitas en morceaux et les frire dans l''huile jusqu''à ce qu''ils soient dorés et croustillants.","Fouetter le yaourt avec le tahini, l''ail écrasé, le jus de citron et le sel jusqu''à obtenir un mélange lisse.","Détendre le yaourt avec quelques cuillères d''eau de cuisson des pois chiches jusqu''à la consistance d''une crème épaisse.","Faire dorer les pignons dans le ghee et retirer du feu.","Étaler le pain frit dans un plat, couvrir des pois chiches chauds et d''un peu de leur jus.","Napper de yaourt, arroser de beurre et de pignons, saupoudrer de paprika et de persil, servir aussitôt."]'::jsonb),
('Bibimbap', 'Riz surmonté de légumes cuits séparément, de viande et d''un œuf, mélangés au gochujang juste avant de manger.', 40, 20, 4, 2, 'protéiné', '["coréen","riz","bowl"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mariner le bœuf dans la sauce soja, l''ail et une cuillère d''huile de sésame pendant 20 min.","Blanchir les épinards 30 sec, les presser et les assaisonner d''huile de sésame et de sel. Cuire les pousses de soja 3 min et les assaisonner de la même façon avec l''ail.","Faire revenir séparément la carotte et les shiitake quelques minutes chacun, en assaisonnant chaque légume individuellement.","Saisir le bœuf à feu vif 2 min. Cuire les œufs sur le plat séparément, jaune coulant.","Répartir le riz chaud dans les bols, disposer les légumes et le bœuf en sections, ajouter l''œuf et une cuillère de gochujang. Chacun mélange le sien."]'::jsonb),
('Baklava', 'Quarante couches de feuilles de yufka à la pistache, imbibées de sirop. Le baklava chaud reçoit le sirop froid, jamais l''inverse.', 60, 60, 12, 3, 'gras', '["turc","dessert","four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préparer le sirop : porter le sucre et l''eau à ébullition, cuire 15 min, ajouter le citron et laisser refroidir complètement.","Faire fondre le beurre et le laisser reposer ; utiliser seulement la couche claire du dessus, jeter le dépôt.","Disposer vingt feuilles dans un plat beurré, en beurrant chacune. Répartir les pistaches en couche régulière.","Couvrir de vingt feuilles supplémentaires, en beurrant chacune, la dernière généreusement.","Découper en losanges avec un couteau bien aiguisé, jusqu''au fond du plat.","Cuire à 170°C pendant 1h, à belle coloration dorée. Verser aussitôt le sirop froid dans les découpes.","Laisser reposer 6h, idéalement toute la nuit, avant de servir."]'::jsonb),
('Moules marinières', 'Moules cuites à la vapeur de vin blanc, céleri et oignon. Cinq minutes sous couvercle, pas plus.', 25, 15, 4, 1, 'light', '["belge","fruits de mer","rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Trier les moules, jeter celles qui sont cassées ou qui ne se referment pas au toucher. Retirer les byssus et rincer.","Faire fondre le beurre et suer échalote, céleri et ail 5 min sans coloration.","Verser le vin, ajouter thym et laurier, porter à ébullition.","Ajouter les moules, couvrir aussitôt et cuire à feu vif 5 min en secouant la marmite deux fois.","Soulever le couvercle : les coquilles doivent être ouvertes ; jeter celles qui ne le sont pas. Parsemer de persil, poivrer et servir avec les frites et le bouillon à part."]'::jsonb),
('Phô bo', 'Un bouillon de bœuf clair au gingembre grillé et épices entières, nouilles de riz et bœuf qui finit de cuire dans le bol.', 30, 240, 4, 3, 'protéiné', '["vietnamien","soupe","mijoté"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir les os d''eau froide, porter à ébullition 10 min, jeter l''eau, rincer les os et la marmite pour un bouillon clair.","Couper oignon et gingembre en deux et griller les faces coupées à sec jusqu''à ce qu''elles noircissent par endroits.","Torréfier les épices à sec, les nouer dans une mousseline. Remettre les os dans la marmite propre avec la poitrine, l''oignon, le gingembre et les épices, couvrir largement d''eau.","Mijoter 3h à frémissement léger, écumer la première demi-heure. Retirer la poitrine après 1h30 et la laisser refroidir.","Filtrer le bouillon, assaisonner de nuoc-mâm et de sucre — il doit être légèrement plus salé qu''agréable seul, car les nouilles en absorberont une partie.","Cuire les nouilles, les répartir dans les bols, disposer la poitrine tranchée et le faux-filet cru dessus. Napper de bouillon bouillant et servir avec les herbes, le citron vert et le piment."]'::jsonb),
('Bánh mì', 'Une baguette française garnie à la vietnamienne : pâté, porc, légumes marinés et coriandre dans un seul sandwich.', 25, 15, 4, 1, 'protéiné', '["vietnamien","sandwich","rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dissoudre vinaigre, sucre et une pincée de sel dans 100ml d''eau tiède, verser sur la carotte et le daikon, laisser mariner 1h.","Mariner le porc dans le nuoc-mâm et une cuillère de sucre 20 min, puis saisir à feu vif 3 min par face jusqu''à caramélisation.","Réchauffer les baguettes 5 min à 200°C pour raviver la croûte. Les fendre sur la longueur sans les séparer.","Tartiner une moitié de pâté et l''autre de mayonnaise. Garnir de porc, de légumes marinés égouttés, de concombre, de coriandre et de piment. Refermer avec la paume et servir aussitôt."]'::jsonb),
('Poulet biryani', 'Riz et poulet mariné cuits ensemble sous couvercle : les couches cuisent à la vapeur plutôt qu''au brassage.', 45, 60, 6, 3, 'protéiné', '["indien","riz","épicé"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer les oignons dans le ghee à coloration profonde, environ 20 min. En réserver la moitié : c''est le birista, l''arôme principal du plat.","Mariner le poulet dans le yaourt avec gingembre, ail, épices, la moitié des oignons dorés, menthe et sel, 1h minimum, idéalement 3h.","Cuire le riz dans une grande quantité d''eau salée avec les épices entières exactement 5 min, puis égoutter.","Étaler le poulet mariné au fond d''une cocotte, couvrir du riz en couche régulière, arroser du lait safrané par endroits et parsemer du reste d''oignons et d''herbes.","Couvrir hermétiquement, 5 min à feu vif puis 40 min à feu très doux, sans jamais soulever le couvercle.","Laisser reposer 10 min puis mélanger une seule fois du bas vers le haut, en soulevant le poulet dans le riz plutôt qu''en remuant."]'::jsonb)

ON CONFLICT (title) DO UPDATE SET
  description = EXCLUDED.description,
  prep_time_mins = EXCLUDED.prep_time_mins,
  cook_time_mins = EXCLUDED.cook_time_mins,
  servings = EXCLUDED.servings,
  difficulty = EXCLUDED.difficulty,
  dietary_type = EXCLUDED.dietary_type,
  tags = EXCLUDED.tags,
  equipment_needed = EXCLUDED.equipment_needed,
  instructions = EXCLUDED.instructions;

-- Nettoyer les anciens ingrédients de ces recettes avant de réinsérer les bonnes quantités
-- (utile si une version précédente de ce fichier a déjà été exécutée).
DELETE FROM recipe_ingredients WHERE recipe_id IN (
  SELECT id FROM recipes WHERE title IN (
    'Ratatouille','Soupe à l''oignon gratinée','Coq au vin','Crème brûlée','Quiche lorraine','Croissant','Bouillabaisse','Tarte Tatin',
    'Blanquette de veau','Cassoulet','Pot-au-feu','Gratin dauphinois','Salade niçoise','Croque-monsieur','Mousse au chocolat','Crêpes',
    'Tarte aux pommes','Poulet basquaise','Choucroute garnie','Clafoutis aux cerises','Tartiflette','Œufs mimosa','Far breton',
    'Soupe au pistou','Camembert rôti au four',
    'Spaghetti carbonara','Risotto alla milanese','Pizza margherita','Lasagnes bolognaise','Tiramisu','Soupe miso','Ramen shoyu',
    'Tempura','Guacamole','Tacos al pastor','Paella valenciana','Moussaka','Souvlaki','Fattet hommous','Bibimbap','Baklava',
    'Moules marinières','Phô bo','Bánh mì','Poulet biryani',
    -- anciens titres v1 remplacés / renommés
    'Pâtes à la Carbonara','Poulet Rôti aux Herbes','Riz Complet aux Légumes','Omelette aux Champignons','Tacos au Poulet',
    'Poke Bowl Saumon','Curry de Pois Chiches','Courgettes Farcies'
  )
);

INSERT INTO recipe_ingredients (recipe_id, ingredient_name, quantity, unit)
SELECT r.id, x.ingredient_name, x.quantity, x.unit
FROM recipes r
JOIN (VALUES
