  ('Soupe à l''oignon gratinée','Oignons',1,'kg'),('Soupe à l''oignon gratinée','Beurre',50,'g'),('Soupe à l''oignon gratinée','Farine',1,'c.à.s'),('Soupe à l''oignon gratinée','Vin blanc sec',150,'ml'),('Soupe à l''oignon gratinée','Bouillon de bœuf',1.2,'L'),('Soupe à l''oignon gratinée','Baguette',8,'tranche'),('Soupe à l''oignon gratinée','Gruyère',150,'g'),('Soupe à l''oignon gratinée','Thym',2,'branche'),('Soupe à l''oignon gratinée','Sel et poivre',1,'à goût'),

