-- ===== Recettes v1 conservées, complétées (rédigées à la main) =====
-- Ces recettes existaient dans la toute première version du seed sans
-- instructions. Elles sont conservées (elles peuvent être en favoris ou au
-- planning) et reçoivent ici une description, des étapes et des quantités
-- complètes. Cuisson à cœur : 74°C pour le poulet, 71°C pour la viande hachée.

INSERT INTO recipes (title, description, prep_time_mins, cook_time_mins, servings, difficulty, dietary_type, tags, visibility, equipment_needed, instructions) VALUES
('Poulet Rôti aux Herbes', 'Un poulet entier rôti au four avec un beurre aux herbes glissé sous la peau : chair juteuse, peau croustillante.', 20, 75, 4, 2, 'protéiné', '["poulet","viande","four","classique"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le poulet du réfrigérateur 30 min avant la cuisson. Préchauffer le four à 210°C (chaleur statique).","Effeuiller la moitié du thym et hacher finement une branche de romarin. Écraser 2 gousses d''ail et les mélanger au beurre mou avec les herbes, 1/2 c.à.c de sel et du poivre.","Sécher le poulet avec du papier absorbant. Décoller délicatement la peau des blancs avec les doigts et glisser le beurre aux herbes dessous, en l''étalant bien.","Couper le citron en quatre et le glisser dans la cavité avec le reste du thym, du romarin et 2 gousses d''ail écrasées. Ficeler les cuisses si possible.","Poser le poulet dans un plat, badigeonner d''huile, saler toute la peau avec le reste du sel et poivrer. Disposer les gousses d''ail restantes autour et verser l''eau au fond du plat.","Enfourner 15 min à 210°C, puis baisser à 190°C et cuire encore 55 à 60 min pour un poulet de 1,6 kg, en arrosant avec le jus du plat toutes les 20 min. Rajouter un peu d''eau si le fond commence à brûler.","Vérifier la cuisson : en piquant la jointure entre la cuisse et le corps, le jus doit couler clair, sans trace rosée (74°C à cœur avec un thermomètre). Sinon, prolonger par tranches de 10 min.","Sortir le poulet, le couvrir de papier aluminium sans serrer et le laisser reposer 10 min avant de découper. Servir avec le jus du plat."]'::jsonb),
('Riz Complet aux Légumes', 'Du riz complet cuit par absorption dans un bouillon, mêlé à des légumes sautés qui restent croquants.', 15, 50, 2, 1, 'light', '["riz","légumes","végétarien","sain"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz complet dans une passoire sous l''eau froide jusqu''à ce que l''eau soit presque claire. Faire chauffer le bouillon.","Dans une casserole, faire revenir la moitié de l''oignon émincé dans 1 c.à.s d''huile 3 min à feu moyen. Ajouter le riz et remuer 1 min pour bien l''enrober.","Verser le bouillon chaud, porter à ébullition, puis couvrir et cuire à feu très doux 40 min sans soulever le couvercle. Retirer du feu et laisser reposer 10 min à couvert : tout le liquide doit être absorbé et le grain tendre mais encore légèrement ferme.","Pendant la cuisson du riz, détailler le brocoli en petits bouquets, la carotte en fines rondelles, la courgette en dés et le poivron en lanières.","Dans une grande poêle, chauffer 1 c.à.s d''huile à feu vif. Faire sauter la carotte et le brocoli 4 min, puis ajouter le poivron, la courgette, le reste de l''oignon et l''ail haché et cuire encore 4 à 5 min en remuant : les légumes doivent être dorés mais croquants.","Déglacer avec la sauce soja, mélanger avec le riz égrené à la fourchette, rectifier l''assaisonnement et servir chaud."]'::jsonb),
('Omelette aux Champignons', 'Une omelette baveuse à la française, garnie de champignons dorés au beurre et de persil.', 5, 10, 1, 1, 'protéiné', '["œufs","champignons","rapide","petit-déjeuner"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Nettoyer les champignons avec un papier humide (ne pas les laisser tremper) et les couper en lamelles. Hacher le persil.","Chauffer une poêle à feu vif avec la moitié du beurre. Quand il mousse, ajouter les champignons en une seule couche et les laisser dorer 5 à 6 min en remuant de temps en temps, jusqu''à ce que leur eau soit évaporée. Saler seulement à la fin, ajouter le persil et réserver dans une assiette.","Battre les œufs à la fourchette avec une pincée de sel et du poivre, juste assez pour mélanger blancs et jaunes.","Essuyer la poêle (20 cm idéalement), la remettre à feu moyen avec le reste du beurre. Quand il mousse sans brunir, verser les œufs.","Remuer vivement avec une spatule pendant 20 à 30 secondes en secouant la poêle, puis laisser prendre sans toucher 1 min : le dessous doit être pris mais le dessus encore crémeux.","Répartir les champignons sur une moitié, replier l''omelette et la faire glisser dans l''assiette. Servir aussitôt."]'::jsonb),
('Tacos au Poulet', 'Des tacos de poulet mariné au citron vert et aux épices, avec pico de gallo et guacamole maison.', 45, 15, 4, 1, 'protéiné', '["mexicain","poulet","street-food"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger le jus d''un citron vert, l''huile, l''ail pressé, le cumin, le paprika fumé, l''origan, le piment et 1 c.à.c de sel. Enrober le poulet de cette marinade et laisser 30 min au réfrigérateur (4h maximum : au-delà, l''acidité rend la viande farineuse).","Pico de gallo : épépiner les tomates et les couper en petits dés, ajouter la moitié de l''oignon rouge finement haché, la moitié de la coriandre ciselée, un filet de jus de citron vert et une pincée de sel.","Guacamole : écraser les avocats à la fourchette avec le jus du dernier demi-citron vert, le reste de l''oignon haché et une pincée de sel. Couvrir au contact d''un film pour éviter qu''il noircisse.","Chauffer une poêle ou une plancha à feu moyen-vif. Égoutter le poulet et le cuire 6 à 7 min par face, jusqu''à ce qu''il soit bien doré et que la chair ne soit plus rosée au centre (74°C à cœur).","Laisser reposer le poulet 5 min sur une planche, puis le trancher en fines lamelles.","Réchauffer les tortillas 30 secondes de chaque côté dans une poêle sèche bien chaude et les garder enveloppées dans un torchon.","Garnir chaque tortilla de poulet, de pico de gallo, de guacamole, d''une cuillère de crème et de coriandre. Servir avec le reste du citron vert en quartiers."]'::jsonb),
('Poke Bowl Saumon', 'Un bol hawaïen de riz vinaigré tiède, de saumon cru mariné à la sauce soja et de légumes croquants.', 30, 15, 2, 1, 'protéiné', '["hawaïen","poisson","frais","bowl"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz à sushi dans plusieurs eaux en le frottant entre les mains, jusqu''à ce que l''eau soit claire. Égoutter 10 min.","Mettre le riz et l''eau dans une casserole, porter à ébullition, couvrir et cuire 12 min à feu très doux. Retirer du feu et laisser reposer 10 min sans ouvrir.","Dissoudre le sucre et le sel dans le vinaigre de riz, verser sur le riz chaud et mélanger délicatement en le soulevant à la spatule. Laisser tiédir.","Utiliser impérativement du saumon vendu qualité sushi / sashimi (ou préalablement congelé 7 jours à -20°C). Le couper en cubes de 1,5 cm.","Mélanger la sauce soja, l''huile de sésame et le gingembre râpé. Y enrober le saumon et laisser mariner 10 à 15 min au réfrigérateur, pas plus.","Cuire les edamames 4 min dans l''eau bouillante salée, les refroidir sous l''eau froide. Couper l''avocat en tranches, le concombre en demi-rondelles, râper la carotte et émincer l''oignon nouveau.","Répartir le riz dans deux bols, disposer le saumon et chaque garniture en sections, arroser du reste de marinade et parsemer de graines de sésame. Servir aussitôt."]'::jsonb),
('Curry de Pois Chiches', 'Un curry végétarien de pois chiches au lait de coco et aux épinards, servi avec du riz basmati.', 15, 35, 4, 1, 'protéiné', '["curry","végétarien","pois-chiches","indien"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer finement l''oignon, hacher l''ail et râper le gingembre. Égoutter et rincer les pois chiches.","Chauffer l''huile dans une sauteuse à feu moyen et faire fondre l''oignon 8 à 10 min en remuant, jusqu''à ce qu''il soit bien doré : c''est la base du goût.","Ajouter l''ail et le gingembre et cuire 1 min. Ajouter le curry en poudre, le cumin et le curcuma et remuer 1 min, jusqu''à ce que les épices embaument sans brûler (ajouter une cuillère d''eau si ça accroche).","Verser les tomates concassées et cuire 5 min pour les réduire un peu. Ajouter le lait de coco, les pois chiches et le sel.","Laisser mijoter à découvert 15 à 20 min à feu doux en remuant de temps en temps, jusqu''à ce que la sauce nappe la cuillère.","Pendant ce temps, rincer le riz basmati, le mettre dans une casserole avec 1,5 fois son volume d''eau et une pincée de sel, porter à ébullition, couvrir et cuire 10 min à feu très doux, puis laisser reposer 5 min à couvert.","Ajouter les épinards au curry et remuer 2 min jusqu''à ce qu''ils tombent. Hors du feu, ajouter le jus du citron vert, rectifier le sel et parsemer de coriandre. Servir avec le riz."]'::jsonb),
('Courgettes Farcies', 'Des courgettes évidées, farcies d''une viande hachée aux herbes et gratinées au four.', 25, 50, 4, 2, 'protéiné', '["légumes","viande","four","provençal"]'::jsonb, 'public', '["stovetop","oven"]'::jsonb, '["Préchauffer le four à 200°C. Couper les courgettes en deux dans la longueur et les évider à la petite cuillère en laissant 5 mm de chair sur les bords. Hacher grossièrement la chair retirée.","Disposer les demi-courgettes dans un plat, face coupée vers le haut, badigeonner d''1 c.à.s d''huile, saler légèrement et précuire 10 min au four : elles ne rendront plus d''eau dans la farce.","Pendant ce temps, faire revenir l''oignon haché dans le reste de l''huile 5 min à feu moyen. Ajouter l''ail haché et la chair de courgette et cuire 5 à 6 min jusqu''à ce que l''eau soit évaporée. Laisser tiédir.","Faire tremper la mie de pain dans le lait puis l''essorer. Dans un saladier, mélanger la viande hachée, le mélange oignon-courgette, la mie de pain, l''œuf, le persil, les herbes de Provence, le sel et du poivre.","Garnir généreusement les demi-courgettes de farce en tassant légèrement, et parsemer de fromage râpé.","Verser l''eau au fond du plat et enfourner 35 à 40 min à 200°C : le dessus doit être bien doré et la farce cuite à cœur (plus de trace rosée au centre, 71°C). Couvrir d''aluminium en fin de cuisson si le fromage colore trop vite.","Laisser reposer 5 min avant de servir."]'::jsonb)
ON CONFLICT (title) DO UPDATE SET
  description = EXCLUDED.description,
  prep_time_mins = EXCLUDED.prep_time_mins,
  cook_time_mins = EXCLUDED.cook_time_mins,
  servings = EXCLUDED.servings,
  difficulty = EXCLUDED.difficulty,
  dietary_type = EXCLUDED.dietary_type,
  tags = EXCLUDED.tags,
  equipment_needed = EXCLUDED.equipment_needed,
  instructions = EXCLUDED.instructions;

