JOIN (VALUES
  ('Poulet Rôti aux Herbes','Poulet entier',1.6,'kg'),('Poulet Rôti aux Herbes','Beurre mou',40,'g'),('Poulet Rôti aux Herbes','Huile d''olive',1,'c.à.s'),('Poulet Rôti aux Herbes','Thym frais',6,'branche'),('Poulet Rôti aux Herbes','Romarin frais',2,'branche'),('Poulet Rôti aux Herbes','Ail',6,'gousse'),('Poulet Rôti aux Herbes','Citron',1,'pièce'),('Poulet Rôti aux Herbes','Sel',2,'c.à.c'),('Poulet Rôti aux Herbes','Poivre',1,'à goût'),('Poulet Rôti aux Herbes','Eau',100,'ml'),

