-- ===== Fin petits-déjeuners & goûters =====


-- ===== Fusion des doublons v1 → v2 =====
-- Trois recettes v1 sont le même plat qu'une recette v2 (titre ou casse
-- différente). Les favoris et le planning qui pointent vers l'ancienne version
-- sont reportés sur la nouvelle, puis l'ancienne est supprimée.

DO $$
DECLARE
  pair RECORD;
BEGIN
  FOR pair IN
    SELECT o.id AS old_id, n.id AS new_id
    FROM (VALUES
      ('pâtes à la carbonara', 'Spaghetti carbonara'),
      ('salade niçoise', 'Salade niçoise'),
      ('soupe à l''oignon', 'Soupe à l''oignon gratinée')
    ) AS m(old_title_lower, new_title)
    JOIN recipes n ON n.title = m.new_title
    JOIN recipes o ON lower(o.title) = m.old_title_lower AND o.id <> n.id
  LOOP
    -- Favori en double (l'utilisateur avait déjà les deux versions) : on garde celui de la v2
    DELETE FROM favorite_recipes f
    WHERE f.recipe_id = pair.old_id
      AND EXISTS (SELECT 1 FROM favorite_recipes f2 WHERE f2.user_id = f.user_id AND f2.recipe_id = pair.new_id);

    UPDATE favorite_recipes SET recipe_id = pair.new_id WHERE recipe_id = pair.old_id;
    UPDATE planned_meals SET recipe_id = pair.new_id WHERE recipe_id = pair.old_id;

    DELETE FROM recipe_ingredients WHERE recipe_id = pair.old_id;
    DELETE FROM recipes WHERE id = pair.old_id;
  END LOOP;
END $$;

-- Catalogue d'ingrédients : retire ceux qui ne sont plus utilisés par aucune recette
DELETE FROM ingredients i
WHERE NOT EXISTS (SELECT 1 FROM recipe_ingredients ri WHERE ri.ingredient_id = i.id);
